_SUP = str.maketrans("-0123456789", "⁻⁰¹²³⁴⁵⁶⁷⁸⁹")


def sci(x, d=4):
    """แสดงตัวเลขแบบอ่านง่าย เช่น 4.260×10⁹"""
    if x == 0:
        return "0"
    e = math.floor(math.log10(abs(x)))
    if -3 <= e < 6:
        return f"{x:,.{max(0, d - 1 - e)}f}"
    return f"{x / 10 ** e:.{d - 1}f}×10{str(e).translate(_SUP)}"


