# ---------------------------------------------------------------------------
# เนื้อหาบรรยาย — เรียบเรียงตามหัวข้อของหนังสือ (เขียนใหม่ทั้งหมด ไม่ได้คัดลอกจากต้นฉบับ)
# รูปแบบข้อความย่อ: ย่อหน้าคั่นด้วยบรรทัดว่าง · "- " = รายการ · บล็อกที่ขึ้นต้นด้วย \[ = สมการ
# · "> " = กล่องหมายเหตุ · **ตัวหนา** · สมการในบรรทัดใช้ \( ... \)
# ---------------------------------------------------------------------------

def _inline(s):
    return re.sub(r"\*\*(.+?)\*\*", r"<b>\1</b>", s)


def md(text):
    out = []
    for block in textwrap.dedent(text).strip().split("\n\n"):
        lines = [l.strip() for l in block.strip().splitlines() if l.strip()]
        if not lines:
            continue
        if all(l.startswith("- ") for l in lines):
            out.append("<ul>" + "".join(f"<li>{_inline(l[2:])}</li>" for l in lines) + "</ul>")
        elif lines[0].startswith("\\["):
            out.append('<div class="eq">' + " ".join(lines) + "</div>")
        elif lines[0].startswith("> "):
            out.append('<div class="note">' + _inline(" ".join(l.lstrip("> ") for l in lines)) + "</div>")
        else:
            out.append("<p>" + _inline(" ".join(lines)) + "</p>")
    # บังคับให้สัญลักษณ์จักรราศีแสดงเป็นตัวอักษร ไม่ใช่ emoji
    return "".join(out).replace("♈", "♈︎").replace("♎", "♎︎")


def sec(title, en, body, figs=(), lab=False):
    return dict(t=title, en=en, html=md(body), figs=list(figs), lab=lab)


