        ("ถ้าจุดเลี้ยวออกของกระจุกอยู่ที่ดาวมวลน้อยลง แสดงว่ากระจุก…", ["แก่กว่า", "อายุน้อยกว่า", "ใกล้กว่า", "ไกลกว่า"], 0, "ดาวมวลมากหมดอายุไปแล้ว เหลือแต่ดาวมวลน้อยบนแถบลำดับหลัก"),
        ("ทำไมกระจุกดาวจึงเหมาะศึกษาวิวัฒนาการดาว?", ["ดาวเกิดพร้อมกัน อยู่ระยะเดียวกัน องค์ประกอบเคมีเดียวกัน", "สว่างที่สุดบนฟ้า", "ไม่มีฝุ่นเลย", "หมุนเร็ว"], 0,
         "ตัวแปรที่ต่างกันจึงเหลือแค่มวล"),
