  b += tx(110, 250, 'k = +1 (ปิด)', { b: 1, s: 12 }) + tx(110, 268, 'Ω > 1 · มุมรวม > 180°', { c: 's' }) + tx(345, 250, 'k = 0 (แบน)', { b: 1, s: 12 }) + tx(345, 268, 'Ω = 1 · มุมรวม = 180°', { c: 's' }) + tx(570, 250, 'k = −1 (เปิด)', { b: 1, s: 12 }) + tx(570, 268, 'Ω < 1 · มุมรวม < 180°', { c: 's' });
